// src/routes/workflows.ts
var router26 = new Hono2();
router26.use("*", requireAuth);
async function getWorkflow(workspaceId, id) {
  const { data } = await supabase.from("nodes").select("id,data,updated_at").eq("workspace_id", workspaceId).eq("object_type", "automation").eq("data->>type", "workflow").eq("id", id).maybeSingle();
  return data;
}
function response2(node) {
  return {
    id: node.id,
    name: node.data.name ?? "Untitled workflow",
    status: node.data.status ?? "draft",
    nodes: Array.isArray(node.data.nodes) ? node.data.nodes : [],
    updated_at: node.updated_at
  };
}
router26.get("/:id", async (c) => {
  if (c.req.param("id") === "new") {
    return c.json({ id: "new", name: "New Workflow", status: "draft", nodes: [] });
  }
  const node = await getWorkflow(c.get("workspaceId"), c.req.param("id"));
  return node ? c.json(response2(node)) : c.json({ error: "Workflow not found" }, 404);
});
router26.patch("/:id", async (c) => {
  const body = await c.req.json();
  const workspaceId = c.get("workspaceId");
  let result;
  if (c.req.param("id") === "new") {
    result = await supabase.from("nodes").insert({
      workspace_id: workspaceId,
      vertical: "shared",
      object_type: "automation",
      data: { ...body, type: "workflow" },
      created_by: c.get("userId")
    }).select("id,data,updated_at").single();
  } else {
    result = await supabase.from("nodes").update({ data: { ...body, type: "workflow" } }).eq("workspace_id", workspaceId).eq("object_type", "automation").eq("id", c.req.param("id")).select("id,data,updated_at").single();
  }
  if (result.error) return c.json({ error: result.error.message }, 400);
  await supabase.from("activities").insert({
    node_id: result.data.id,
    workspace_id: workspaceId,
    actor_type: "human",
    actor_id: c.get("userId"),
    action: c.req.param("id") === "new" ? "created" : "updated",
    diff: { workflow: true }
  });
  return c.json(response2(result.data));
});
router26.delete("/:id", async (c) => {
  const { error } = await supabase.from("nodes").delete().eq("workspace_id", c.get("workspaceId")).eq("object_type", "automation").eq("id", c.req.param("id"));
  return error ? c.json({ error: error.message }, 400) : c.json({ ok: true });
});

// src/routes/invoices.ts
var router27 = new Hono2();
router27.use("*", requireAuth);
var lineItemSchema = external_exports.object({
  description: external_exports.string(),
  quantity: external_exports.number().positive(),
  unit_price: external_exports.number().min(0),
  tax_rate: external_exports.number().min(0).max(100).default(0)
});
var invoiceBodySchema = external_exports.object({
  number: external_exports.string().optional(),
  client_name: external_exports.string().min(1),
  client_email: external_exports.string().email().optional(),
  client_address: external_exports.string().optional(),
  line_items: external_exports.array(lineItemSchema).min(1),
  currency: external_exports.string().default("GBP"),
  due_date: external_exports.string().optional(),
  notes: external_exports.string().optional(),
  status: external_exports.enum(["draft", "sent", "viewed", "paid", "overdue", "cancelled"]).default("draft")
});
function calcTotals(lineItems) {
  const subtotal = lineItems.reduce((s, i) => s + i.quantity * i.unit_price, 0);
  const tax_total = lineItems.reduce((s, i) => s + i.quantity * i.unit_price * (i.tax_rate / 100), 0);
  return { subtotal, tax_total, total: subtotal + tax_total };
}
async function nextInvoiceNumber(workspaceId) {
  const { count } = await supabase.from("nodes").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("vertical", "finance").eq("object_type", "invoice");
  const n = (count ?? 0) + 1;
  return `INV-${String(n).padStart(4, "0")}`;
}
router27.get("/", async (c) => {
  const status = c.req.query("status");
  const search = c.req.query("search") ?? "";
  let query = supabase.from("nodes").select("id,data,created_at,updated_at,created_by").eq("workspace_id", c.get("workspaceId")).eq("vertical", "finance").eq("object_type", "invoice").order("created_at", { ascending: false });
  if (status) query = query.eq("data->>status", status);
  const { data, error } = await query;
  if (error) return c.json({ error: error.message }, 500);
  const result = (data ?? []).filter((row) => {
    if (!search) return true;
    const d = row.data;
    return String(d.number ?? "").toLowerCase().includes(search.toLowerCase()) || String(d.client_name ?? "").toLowerCase().includes(search.toLowerCase()) || String(d.client_email ?? "").toLowerCase().includes(search.toLowerCase());
  }).map((row) => ({ id: row.id, ...row.data, created_at: row.created_at, updated_at: row.updated_at, created_by: row.created_by }));
  return c.json(result);
});
router27.get("/:id", async (c) => {
  const { data, error } = await supabase.from("nodes").select("id,data,created_at,updated_at,created_by").eq("workspace_id", c.get("workspaceId")).eq("id", c.req.param("id")).eq("vertical", "finance").eq("object_type", "invoice").maybeSingle();
  if (error) return c.json({ error: error.message }, 500);
  if (!data) return c.json({ error: "Not found" }, 404);
  return c.json({ id: data.id, ...data.data, created_at: data.created_at, updated_at: data.updated_at, created_by: data.created_by });
});
router27.post("/", zValidator("json", invoiceBodySchema), async (c) => {
  const body = c.req.valid("json");
  const number = body.number || await nextInvoiceNumber(c.get("workspaceId"));
  const { subtotal, tax_total, total } = calcTotals(body.line_items);
  const invoiceData = {
    number,
    client_name: body.client_name,
    client_email: body.client_email ?? null,
    client_address: body.client_address ?? null,
    line_items: body.line_items,
    currency: body.currency,
    subtotal,
    tax_total,
    total,
    status: body.status,
    due_date: body.due_date ?? null,
    notes: body.notes ?? null,
    sent_at: null,
    paid_at: null,
    chase_count: 0
  };
  const { data, error } = await supabase.from("nodes").insert({
    workspace_id: c.get("workspaceId"),
    vertical: "finance",
    object_type: "invoice",
    data: invoiceData,
    created_by: c.get("userId")
  }).select("id,data,created_at,created_by").single();
  if (error) return c.json({ error: error.message }, 500);
  return c.json({ id: data.id, ...data.data, created_at: data.created_at, created_by: data.created_by }, 201);
});
router27.patch("/:id", zValidator("json", invoiceBodySchema.partial()), async (c) => {
  const { data: existing, error: fetchErr } = await supabase.from("nodes").select("id,data").eq("workspace_id", c.get("workspaceId")).eq("id", c.req.param("id")).eq("vertical", "finance").eq("object_type", "invoice").maybeSingle();
  if (fetchErr) return c.json({ error: fetchErr.message }, 500);
  if (!existing) return c.json({ error: "Not found" }, 404);
  const body = c.req.valid("json");
  const current = existing.data;
  const lineItems = body.line_items ?? current.line_items;
  const { subtotal, tax_total, total } = calcTotals(lineItems);
  const statusUpdates = {};
  if (body.status === "sent" && !current.sent_at) statusUpdates.sent_at = (/* @__PURE__ */ new Date()).toISOString();
  if (body.status === "paid" && !current.paid_at) statusUpdates.paid_at = (/* @__PURE__ */ new Date()).toISOString();
  const updatedData = {
    ...current,
    ...body,
    line_items: lineItems,
    subtotal,
    tax_total,
    total,
    ...statusUpdates
  };
  const { data, error } = await supabase.from("nodes").update({ data: updatedData, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", c.req.param("id")).select("id,data,updated_at").single();
  if (error) return c.json({ error: error.message }, 500);
  return c.json({ id: data.id, ...data.data, updated_at: data.updated_at });
});
router27.delete("/:id", async (c) => {
  const { error } = await supabase.from("nodes").delete().eq("workspace_id", c.get("workspaceId")).eq("id", c.req.param("id")).eq("vertical", "finance").eq("object_type", "invoice");
  if (error) return c.json({ error: error.message }, 500);
  return c.json({ ok: true });
});

